#!/usr/bin/env python3
"""Generates crates/model/src/countries.rs from the game's country enum (best.ac)."""
import os
import re

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "../.."))
src = open(os.path.expanduser("~/brasfoot-mods/src/best/ac.java"), encoding="utf-8").read()
rows = re.findall(r'^   \w+\(M\.getString\("P(\d+)"\), "(\w+)", (\d+), (-?\d+), (\d+), aq\.(\w+), aq\.(\w+)\)[,;]', src, re.M)
out = [
    "// Generated by tools/modelgen/gen_countries.py from best.ac. Do not edit.",
    "//! The game's countries (`best.ac`, looked up as `ac.valueOf(\"P\" + id)`). Their names are",
    "//! catalog text (`country-<code>` in the i18n catalogs), not data.",
    "",
    "/// One country: id, three-letter code, confederation (`gg()`: 0 Europe, 1 South America,",
    "/// 2 Africa, 3 Asia, 4 North and Central America, 5 Oceania), level (`getNivel()`), and the",
    "/// two `aq` color tables of its flag.",
    "#[derive(Clone, Copy, Debug, PartialEq, Eq)]",
    "pub struct CountryInfo {",
    "    pub id: i32,",
    "    pub code: &'static str,",
    "    pub confederation: i32,",
    "    pub level: i32,",
    "    pub color_table1: &'static str,",
    "    pub color_table2: &'static str,",
    "}",
    "",
    f"pub const COUNTRIES: [CountryInfo; {len(rows)}] = [",
]
for i, (key, code, ident, conf, level, c1, c2) in enumerate(rows):
    assert int(key) == int(ident) == i, (key, ident, i)
    out.append(f'    CountryInfo {{ id: {ident}, code: "{code}", confederation: {conf}, level: {level}, color_table1: "{c1}", color_table2: "{c2}" }},')
out += ["];", "", "/// `ac.valueOf(\"P\" + id)`.", "pub fn country(id: i32) -> Option<&'static CountryInfo> {",
        "    usize::try_from(id).ok().and_then(|i| COUNTRIES.get(i))", "}", "",
        "/// `ac.valueOf(\"P\" + id).gg()`; the game would throw for an unknown id.",
        "pub fn confederation(id: i32) -> i32 {", "    country(id).map(|c| c.confederation).unwrap_or(-1)", "}", ""]
# the flag colors of best.aq the countries use
aq = open(os.path.expanduser("~/brasfoot-mods/src/best/aq.java"), encoding="utf-8").read()
tables = {}
for name, values in re.findall(r'public static final int\[\] (q\w+) = new int\[\]\{([\d, ]+)\};', aq):
    tables[name] = [int(v) for v in values.split(",")]
for name in re.findall(r'public static final int\[\] (q\w+) = new int\[3\];', aq):
    tables[name] = [0, 0, 0]
used = sorted({c for row in rows for c in row[5:7]})
out += ["/// The RGB of a flag color table of `best.aq`.", "pub fn flag_color(table: &str) -> [u8; 3] {", "    match table {"]
for name in used:
    r, g, b = tables[name]
    out.append(f'        "{name}" => [{r}, {g}, {b}],')
out += ["        _ => [0, 0, 0],", "    }", "}", ""]
open(os.path.join(ROOT, "crates/model/src/countries.rs"), "w").write("\n".join(out))
print(len(rows), "countries")
